```
package com.mindarray.datastore;

import com.mindarray.Bootstrap;
import com.mindarray.api.RemoteEventProcessor;
import com.mindarray.eventbus.EventBusConstants;
import com.mindarray.util.Logger;
import com.mindarray.util.MotadataConfigUtil;
import io.vertx.core.AbstractVerticle;
import io.vertx.core.Promise;
import io.vertx.core.json.JsonObject;

import static com.mindarray.GlobalConstants.*;
import static com.mindarray.eventbus.EventBusConstants.*;

public class EventDatastore extends AbstractVerticle {
    private static final Logger LOGGER = new Logger(EventDatastore.class, MOTADATA_DATASTORE, "Event Datastore Manager");
    private DatastoreEngine eventEngine;
    private String uuid;

    @Override
    public void start(Promise<Void> promise) throws Exception {
        try {
            vertx.eventBus().<JsonObject>localConsumer(EVENT_DATASTORE_STATUS, message -> {
                var event = message.body();

                if (uuid.equalsIgnoreCase(event.getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID))) {
                    LOGGER.trace(String.format("updating status for  %s : %s ", event.getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID), event.getString(STATUS)));
                    eventEngine.setStatus(event.getString(STATUS).equalsIgnoreCase(STATUS_UP));
                }
            });

            eventEngine = new DatastoreEngine().setEventType(config().getString(EventBusConstants.EVENT_TYPE))
                    .setPersistEventOffset(true).setStatus(false).setPause(true).setLogger(LOGGER).setEventHandler(this::send).start(vertx, promise);
            uuid = config().getString(EventBusConstants.EVENT_TYPE).split(DOT_SEPARATOR_ESCAPE)[3];
            if (MotadataConfigUtil.getInstallationMode().equalsIgnoreCase(InstallationMode.SECONDARY.name()) || MotadataConfigUtil.getInstallationMode().equalsIgnoreCase(InstallationMode.FAILOVER.name())) {
                vertx.eventBus().<Void>localConsumer(config().getString(EventBusConstants.EVENT_TYPE) + ".inactive", handler -> eventEngine.setStatus(false));
            }
        } catch (Exception exception) {
            LOGGER.error(exception);
        }
    }

    private void send(JsonObject event) {
        if (Bootstrap.bootstrapType() == BootstrapType.APP) {
            if (MotadataConfigUtil.getInstallationMode().equalsIgnoreCase(InstallationMode.STANDALONE.name()) || MotadataConfigUtil.getInstallationMode().equalsIgnoreCase(InstallationMode.PRIMARY.name())) {
                vertx.eventBus().send(EVENT_PUBLICATION_DATASTORE_WRITE, event.put(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID, uuid).put(EVENT_TOPIC, DATASTORE_BROKER_OPERATION_TOPIC));
                LOGGER.trace(String.format("event sent to datastore %s ", uuid));
            } else {
                vertx.eventBus().send(EVENT_REMOTE, event.put(EVENT_TYPE, EVENT_HA_DATASTORE_SECONDARY_SYNC));
                LOGGER.trace("datastore event sent to primary app");
            }
        }
    }

    @Override
    public void stop(Promise<Void> promise) throws Exception {
        try {
            eventEngine.stop(vertx, promise);
        } catch (Exception exception) {
            LOGGER.error(exception);
        }
    }
}
